window.__votdWeek && window.__votdWeek({"week":"2029-07-16","reading":"Doctrine and Covenants 77–80","days":[{"d":"2029-07-16","ref":"D&C 77:1","b":"D&C","c":77,"v":1,"he":"שְׁאֵלָה מָה יָּם הַזְּכוּכִית הַנִּזְכָּר בְּיַד יוֹחָנָן בַּפֶּרֶק הָרְבִיעִי וְהַפָּסוּק הַשִּׁשִּׁי לֶחָזוֹן תְּשׁוּבָה הִיא הָאָרֶץ בִּהְיוֹתָהּ מְקֻדֶּשֶׁת בְּלֹא מָוֶת וְנִצְחִית׃","en":"Q. What is the sea of glass spoken of by John, 4th chapter, and 6th verse of the Revelation? A. It is the earth, in its sanctified, immortal, and eternal state."},{"d":"2029-07-17","ref":"D&C 77:4","b":"D&C","c":77,"v":4,"he":"שְׁאֵלָה מָה עָלֵינוּ לְהָבִין מֵהָעֵינַיִם וְהַכְּנָפַיִם אֲשֶׁר לַחַיּוֹת תְּשׁוּבָה עֵינֵיהֶן מָשָׁל לְאוֹר וְדָעַת כִּי הֵנָּה מְלֵאוֹת דָּעַת וּכְנָפֵיהֶן מָשָׁל לִגְבוּרָה לָנוּעַ לִפְעֹל וְגוֹ׳׃","en":"Q. What are we to understand by the eyes and wings, which the beasts had? A. Their eyes are a representation of light and knowledge, that is, they are full of knowledge; and their wings are a representation of power, to move, to act, etc."},{"d":"2029-07-18","ref":"D&C 78:18","b":"D&C","c":78,"v":18,"he":"וְלֹא תוּכְלוּ לָשֵׂאת הַכֹּל עַתָּה אַךְ הִתְחַזְּקוּ כִּי אֲנִי אוֹבִילְכֶם לָכֶם הַמַּלְכוּת וּבִרְכוֹתֶיהָ לָכֶם וְעֹשֶׁר הַנֶּצַח לָכֶם׃","en":"And ye cannot bear all things now; nevertheless, be of good cheer, for I will lead you along. The kingdom is yours and the blessings thereof are yours, and the riches of eternity are yours."},{"d":"2029-07-19","ref":"D&C 78:19","b":"D&C","c":78,"v":19,"he":"וְהַמְקַבֵּל הַכֹּל בְּתוֹדָה יֵעָשֶׂה נִכְבָּד וְדִבְרֵי הָאָרֶץ הַזֹּאת יִוָּסְפוּ לוֹ גַּם מֵאָה שְׁעָרִים אָכֵן וְיוֹתֵר׃","en":"And he who receiveth all things with thankfulness shall be made glorious; and the things of this earth shall be added unto him, even an hundred fold, yea, more."},{"d":"2029-07-20","ref":"D&C 79:2","b":"D&C","c":79,"v":2,"he":"וְאֶשְׁלַח עָלָיו אֶת־הַמְּנַחֵם אֲשֶׁר יְלַמְּדֶנּוּ אֶת־הָאֱמֶת וְאֶת הַדֶּרֶךְ אֲשֶׁר יֵלֵךְ בָּהּ׃","en":"And I will send upon him the Comforter, which shall teach him the truth and the way whither he shall go;"},{"d":"2029-07-21","ref":"D&C 79:3","b":"D&C","c":79,"v":3,"he":"וּכְפִי אֲשֶׁר הוּא נֶאֱמָן אָשׁוּב אֲעַטְּרֵהוּ בׇּעֳמָרִים׃","en":"And inasmuch as he is faithful, I will crown him again with sheaves."},{"d":"2029-07-22","ref":"D&C 80:2","b":"D&C","c":80,"v":2,"he":"וּכְפִי אֲשֶׁר אַתָּה חָפֵץ בְּחָבֵר אֶתֵּן לְךָ אֶת־עַבְדִּי עֵדֶן סְמִית׃","en":"And inasmuch as you desire a companion, I will give unto you my servant Eden Smith."}]});
